package runtimesignals

import (
	"sync"

	"github.com/easel/fizeau/internal/provider/quotaheaders"
)

// headerStore holds the most recently observed rate-limit signal per provider.
// Signals are sourced from HTTP response headers parsed by the quotaheaders
// package (extends commit 7776890e quota_exhausted path).
type headerStore struct {
	mu      sync.RWMutex
	signals map[string]quotaheaders.Signal
}

func newHeaderStore() *headerStore {
	return &headerStore{signals: make(map[string]quotaheaders.Signal)}
}

// record stores the signal for provider. Signals where Present is false are
// silently dropped so that responses without rate-limit headers do not clear
// a previously recorded signal.
func (s *headerStore) record(provider string, sig quotaheaders.Signal) {
	if !sig.Present {
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	s.signals[provider] = sig
}

// get returns the last recorded signal for provider. The second return value
// is false when no signal has been recorded yet.
func (s *headerStore) get(provider string) (quotaheaders.Signal, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	sig, ok := s.signals[provider]
	return sig, ok
}

package serviceimpl

import "time"

// Clock is the API-neutral time seam used by service implementation state.
// It deliberately has no dependency on root package contract types so the
// root facade can import this package without creating a cycle.
type Clock func() time.Time

// SystemClock returns the current UTC wall-clock time.
func SystemClock() time.Time {
	return time.Now().UTC()
}

// RuntimeDeps groups constructor dependencies that are safe to pass from the
// root facade into internal implementation packages.
type RuntimeDeps struct {
	Now Clock
}

// Runtime is implementation-local service state that can be constructed from
// the root facade without depending on root public contract types.
type Runtime struct {
	deps RuntimeDeps
}

// NewRuntime constructs implementation state with defaulted dependencies.
func NewRuntime(deps RuntimeDeps) Runtime {
	return Runtime{deps: RuntimeDeps{Now: deps.Clock()}}
}

// Clock returns the configured clock or the system clock when no test seam is
// supplied.
func (d RuntimeDeps) Clock() Clock {
	if d.Now != nil {
		return d.Now
	}
	return SystemClock
}

// Now returns the runtime clock value normalized to UTC.
func (r Runtime) Now() time.Time {
	return r.deps.Clock()().UTC()
}

