	Harness                   string
	WorkDir                   string
	Temperature               *float32
	TopP                      *float64
	TopK                      *int
	MinP                      *float64
	RepetitionPenalty         *float64
	Seed                      *int64
	SamplingSource            string
	Reasoning                 agentcore.Reasoning
	NoStream                  bool
	Permissions               string
	Tools                     []agentcore.Tool
	ToolPreset                string
	PlanningMode              bool
	MaxIterations             int
	MaxTokens                 int
	ReasoningByteLimit        int
	ProviderTimeout           time.Duration
	Timeout                   time.Duration
	CachePolicy               string
