// Package openaicompat contains shared OpenAI-compatible Chat Completions
// protocol plumbing. Provider identity, cost attribution, routing, and
// provider-specific discovery live in provider packages above this layer.
package openaicompat

import (
	"context"
	"encoding/json"
	"net/http"
	"strings"
	"time"

	agent "github.com/easel/fizeau/internal/core"
	"github.com/easel/fizeau/internal/provider/quotaheaders"
	oai "github.com/openai/openai-go"
	"github.com/openai/openai-go/option"
	"github.com/openai/openai-go/packages/param"
)

// Config contains the protocol/client settings shared by providers that speak
// the OpenAI-compatible Chat Completions API.
type Config struct {
	BaseURL string
	APIKey  string
	Headers map[string]string
	// QuotaHeaderParser, when set, is called on every response to convert
	// the response Header into a quotaheaders.Signal. The signal is then
	// forwarded to QuotaSignalObserver. Different providers (OpenAI vs
	// OpenRouter) use different parsers, so the protocol layer takes the
	// parser as a function and stays provider-agnostic.
	QuotaHeaderParser func(http.Header, time.Time) quotaheaders.Signal
	// QuotaSignalObserver, when set together with QuotaHeaderParser, receives
	// the parsed signal on every response. The service layer wires this to
	// the provider quota state machine.
	QuotaSignalObserver func(quotaheaders.Signal)
}

// Client wraps openai-go with agent-native request and response conversion.
type Client struct {
	client *oai.Client
}

// NewClient creates an OpenAI-compatible protocol client.
func NewClient(cfg Config) *Client {
	opts := []option.RequestOption{
		option.WithBaseURL(cfg.BaseURL),
		option.WithMaxRetries(0),
	}
	if cfg.APIKey != "" {
		opts = append(opts, option.WithAPIKey(cfg.APIKey))
	} else {
		opts = append(opts, option.WithAPIKey("not-needed"))
	}
	for k, v := range cfg.Headers {
		opts = append(opts, option.WithHeader(k, v))
	}
	// SSE comment-frame filter must sit before the debug sink so the sink
	// observes the same byte stream the decoder will see. Middlewares are
	// applied in registration order, outermost first.
	opts = append(opts, option.WithMiddleware(SSEFilterMiddleware()))
	if s := ResolveDebugSink(); s != nil {
		opts = append(opts, option.WithMiddleware(DebugMiddleware(s)))
	}
	if cfg.QuotaHeaderParser != nil && cfg.QuotaSignalObserver != nil {
		opts = append(opts, option.WithMiddleware(quotaHeaderMiddleware(cfg.QuotaHeaderParser, cfg.QuotaSignalObserver)))
	}

	client := oai.NewClient(opts...)
	return &Client{client: &client}
}

// quotaHeaderMiddleware returns a middleware that runs `parser` on every
// response Header and forwards the resulting Signal to `observer`. The
// middleware is a no-op when the upstream call returns an error before a
// Response is produced, and runs *after* the response has been received but
// *before* the SDK consumes its body — both branches still surface the same
// (resp, err) tuple to the caller.
func quotaHeaderMiddleware(parser func(http.Header, time.Time) quotaheaders.Signal, observer func(quotaheaders.Signal)) option.Middleware {
	return func(req *http.Request, next option.MiddlewareNext) (*http.Response, error) {
		resp, err := next(req)
		if resp != nil {
			signal := parser(resp.Header, time.Now())
			if signal.Present {
				observer(signal)
			}
		}
		return resp, err
	}
}

// RequestOptions are request controls that map directly to the compatible Chat
// Completions wire shape. ExtraOptions carries provider-owned extensions such
// as non-standard reasoning/thinking fields.
type RequestOptions struct {
	MaxTokens int
	// Temperature/TopP/TopK/MinP/RepetitionPenalty are sampling controls.
	// TopP is OpenAI-standard; TopK / MinP / RepetitionPenalty are
	// non-standard OpenAI-compat extras that omlx, lmstudio, vLLM, and
	// llama.cpp accept as top-level body fields. Nil means unset
	// (server default applies). RepetitionPenalty > 1.0 prevents
	// exact-token loops.
	Temperature       *float64
	TopP              *float64
	TopK              *int
	MinP              *float64
	RepetitionPenalty *float64
	Seed              int64
	Stop              []string
	ExtraOptions      []option.RequestOption
	// CachePolicy mirrors agent.Options.CachePolicy. The OpenAI-compatible
	// protocol layer does not act on it today; it is plumbed so a future
	// caching-aware OpenAI-style provider has a typed field to consume.
	CachePolicy string
}

// ChatResult is a protocol-level non-streaming response without provider
// identity metadata.
type ChatResult struct {
	Model        string
	Content      string
	FinishReason string
	ToolCalls    []agent.ToolCall
	Usage        agent.TokenUsage
	RawUsage     string
}

// CostHook extracts provider-owned cost data from a raw usage object. The SDK
// only calls the hook; it does not know provider-specific attribution rules.
type CostHook func(rawUsage string) *agent.CostAttribution

// StreamAttemptHook builds provider-owned final attempt metadata for a stream.
type StreamAttemptHook func(responseModel string, cost *agent.CostAttribution) *agent.AttemptMetadata

// StreamHooks are optional provider callbacks used by streaming conversion.
type StreamHooks struct {
	Cost    CostHook
	Attempt StreamAttemptHook
}

// Chat executes one non-streaming Chat Completions request.
func (c *Client) Chat(ctx context.Context, model string, messages []agent.Message, tools []agent.ToolDef, opts RequestOptions) (ChatResult, error) {
	params := buildParams(model, messages, tools, opts)
	completion, err := c.client.Chat.Completions.New(ctx, params, opts.ExtraOptions...)
	if err != nil {
		return ChatResult{}, err
	}

	result := ChatResult{
		Model:    completion.Model,
		RawUsage: completion.Usage.RawJSON(),
	}
	msgReasoningContent := extractMessageReasoningContent(completion.RawJSON())
	if completion.Usage.TotalTokens != 0 {
		result.Usage = tokenUsage(
			int(completion.Usage.PromptTokens),
			int(completion.Usage.CompletionTokens),
			int(completion.Usage.TotalTokens),
			int(completion.Usage.PromptTokensDetails.CachedTokens),
		)
		result.Usage.Reasoning, result.Usage.ReasoningTokensApprox = extractReasoningTokens(result.RawUsage, msgReasoningContent)
	}

	if len(completion.Choices) > 0 {
		choice := completion.Choices[0]
		result.Content = choice.Message.Content
		result.FinishReason = string(choice.FinishReason)
		result.ToolCalls = extractToolCalls(choice.Message.ToolCalls)
	}

	return result, nil
}

// ChatStream executes one streaming Chat Completions request and converts
// chunks into agent stream deltas.
func (c *Client) ChatStream(ctx context.Context, model string, messages []agent.Message, tools []agent.ToolDef, opts RequestOptions, hooks StreamHooks) (<-chan agent.StreamDelta, error) {
	params := buildParams(model, messages, tools, opts)
	params.StreamOptions = oai.ChatCompletionStreamOptionsParam{
		IncludeUsage: oai.Bool(true),
	}

	stream := c.client.Chat.Completions.NewStreaming(ctx, params, opts.ExtraOptions...)

	ch := make(chan agent.StreamDelta, 1)
	go func() {
		defer close(ch)
		send := func(delta agent.StreamDelta) {
			delta.ArrivedAt = time.Now()
			ch <- delta
		}

		// OpenAI only sends tool call ID in the first chunk for each index;
		// subsequent argument chunks carry the index but have an empty ID.
		indexToID := make(map[int]string)
		responseModel := model
		var streamCost *agent.CostAttribution
		var aggReasoningContent strings.Builder
		for stream.Next() {
			chunk := stream.Current()
			if chunk.Model != "" {
				responseModel = chunk.Model
			}
			if hooks.Cost != nil {
				if cost := hooks.Cost(chunk.Usage.RawJSON()); cost != nil {
					streamCost = cost
				}
			}

			reasoningContent := extractReasoningContent(chunk.RawJSON())
			if reasoningContent != "" {
				aggReasoningContent.WriteString(reasoningContent)
			}

			if len(chunk.Choices) > 0 {
				choice := chunk.Choices[0]

				for _, tc := range choice.Delta.ToolCalls {
					id := tc.ID
					if id != "" {
						indexToID[int(tc.Index)] = id
					} else {
						id = indexToID[int(tc.Index)]
					}
					send(agent.StreamDelta{
						Model:        chunk.Model,
						ToolCallID:   id,
						ToolCallName: tc.Function.Name,
						ToolCallArgs: tc.Function.Arguments,
					})
				}

				if choice.Delta.Content != "" || choice.FinishReason != "" || reasoningContent != "" {
					send(agent.StreamDelta{
						Model:            chunk.Model,
						Content:          choice.Delta.Content,
						ReasoningContent: reasoningContent,
						FinishReason:     string(choice.FinishReason),
					})
				} else if len(choice.Delta.ToolCalls) == 0 {
					send(agent.StreamDelta{
						Model:        chunk.Model,
						FinishReason: string(choice.FinishReason),
					})
				}
			} else {
				send(agent.StreamDelta{Model: chunk.Model})
			}

			if chunk.Usage.TotalTokens != 0 {
				usage := tokenUsage(
					int(chunk.Usage.PromptTokens),
					int(chunk.Usage.CompletionTokens),
					int(chunk.Usage.TotalTokens),
					int(chunk.Usage.PromptTokensDetails.CachedTokens),
				)
				usage.Reasoning, usage.ReasoningTokensApprox = extractReasoningTokens(chunk.Usage.RawJSON(), aggReasoningContent.String())
				send(agent.StreamDelta{Usage: &usage})
			}
		}

		if err := stream.Err(); err != nil {

---
		if err := stream.Err(); err != nil {
			send(agent.StreamDelta{Err: classifyStreamErr(err)})
			return
		}

		done := agent.StreamDelta{
			Model: responseModel,
			Done:  true,
		}
		if hooks.Attempt != nil {
			done.Attempt = hooks.Attempt(responseModel, streamCost)
		}
		send(done)
	}()

	return ch, nil
}

func buildParams(model string, messages []agent.Message, tools []agent.ToolDef, opts RequestOptions) oai.ChatCompletionNewParams {
	params := oai.ChatCompletionNewParams{
		Model:    model,
		Messages: convertMessages(messages),
	}
	if len(tools) > 0 {
		params.Tools = convertTools(tools)
	}
	if opts.MaxTokens > 0 {
		params.MaxTokens = oai.Int(int64(opts.MaxTokens))
	}
	if opts.Temperature != nil {
		params.Temperature = oai.Float(*opts.Temperature)
	}
	if opts.TopP != nil {
		params.TopP = oai.Float(*opts.TopP)
	}
	if opts.Seed != 0 {
		params.Seed = oai.Int(opts.Seed)
	}
	if len(opts.Stop) > 0 {
		params.Stop = oai.ChatCompletionNewParamsStopUnion{OfStringArray: opts.Stop}
	}
	return params
}

func convertMessages(msgs []agent.Message) []oai.ChatCompletionMessageParamUnion {
	var result []oai.ChatCompletionMessageParamUnion
	for _, m := range msgs {
		switch m.Role {
		case agent.RoleSystem:
			result = append(result, oai.SystemMessage(m.Content))
		case agent.RoleUser:
			result = append(result, oai.UserMessage(m.Content))
		case agent.RoleAssistant:
			if len(m.ToolCalls) > 0 {
				var toolCalls []oai.ChatCompletionMessageToolCallParam
				for _, tc := range m.ToolCalls {
					toolCalls = append(toolCalls, oai.ChatCompletionMessageToolCallParam{
						ID: tc.ID,
						Function: oai.ChatCompletionMessageToolCallFunctionParam{
							Name:      tc.Name,
							Arguments: string(tc.Arguments),
						},
					})
				}
				assistant := oai.ChatCompletionAssistantMessageParam{
					Content: oai.ChatCompletionAssistantMessageParamContentUnion{
						OfString: param.NewOpt(m.Content),
					},
					ToolCalls: toolCalls,
				}
				result = append(result, oai.ChatCompletionMessageParamUnion{OfAssistant: &assistant})
			} else {
				result = append(result, oai.AssistantMessage(m.Content))
			}
		case agent.RoleTool:
			result = append(result, oai.ToolMessage(m.Content, m.ToolCallID))
		}
	}
	return result
}

func convertTools(tools []agent.ToolDef) []oai.ChatCompletionToolParam {
	var result []oai.ChatCompletionToolParam
	for _, t := range tools {
		var params map[string]interface{}
		_ = json.Unmarshal(t.Parameters, &params)

		result = append(result, oai.ChatCompletionToolParam{
			Function: oai.FunctionDefinitionParam{
				Name:        t.Name,
				Description: oai.String(t.Description),
				Parameters:  oai.FunctionParameters(params),
			},
		})
	}
	return result
}

func extractToolCalls(calls []oai.ChatCompletionMessageToolCall) []agent.ToolCall {
	if len(calls) == 0 {
		return nil
	}
	var result []agent.ToolCall
	for _, c := range calls {
		result = append(result, agent.ToolCall{
			ID:        c.ID,
			Name:      c.Function.Name,
			Arguments: json.RawMessage(c.Function.Arguments),
		})
	}
	return result
}

func extractReasoningContent(rawJSON string) string {
	if rawJSON == "" {
		return ""
	}
	var raw struct {
		Choices []struct {
			Delta struct {
				ReasoningContent string `json:"reasoning_content"`
			} `json:"delta"`
		} `json:"choices"`
	}
	if err := json.Unmarshal([]byte(rawJSON), &raw); err != nil || len(raw.Choices) == 0 {
		return ""
	}
	return raw.Choices[0].Delta.ReasoningContent
}

func tokenUsage(input, output, total, cacheRead int) agent.TokenUsage {
	usage := agent.TokenUsage{
		Input:  input,
		Output: output,
		Total:  total,
	}
	if cacheRead > 0 {
		usage.CacheRead = cacheRead
	}
	return usage
}

// extractReasoningTokens resolves the reasoning token count per ADR-010
// Amendment §8. Resolution chain:
//  1. usage.completion_tokens_details.reasoning_tokens (authoritative; even
//     an explicit zero is honoured — the provider signalled no reasoning ran).
//  2. Top-level usage.reasoning_tokens > 0 (non-standard servers).
//  3. char-count(reasoningContent)÷4 when the usage path is absent AND
//     reasoningContent is non-empty. Returns approx=true.
//
// The char-count/4 estimator is a v1 placeholder (4 chars ≈ 1 token for
// English; accuracy degrades for CJK or heavily-symbolic content). A future
// bead can replace it with a real tokenizer once measurement shows the
// approximation error matters in practice.
//
// Returns (tokens, approx). approx is true only in case 3.
func extractReasoningTokens(rawUsageJSON, reasoningContent string) (int, bool) {
	if rawUsageJSON == "" {
		if reasoningContent != "" {
			return len(reasoningContent) / 4, true
		}
		return 0, false
	}
	var raw struct {
		CompletionTokensDetails struct {
			// Pointer so absent vs. explicit-zero are distinguishable: nil means
			// the field was not present; &0 means the server said "no reasoning".
			ReasoningTokens *int `json:"reasoning_tokens"`
		} `json:"completion_tokens_details"`
		// Some non-OpenAI servers put reasoning_tokens at the top level.
		ReasoningTokens *int `json:"reasoning_tokens,omitempty"`
	}
	if err := json.Unmarshal([]byte(rawUsageJSON), &raw); err != nil {
		return 0, false
	}
	if raw.CompletionTokensDetails.ReasoningTokens != nil {
		// Field present — respect the value even if zero (provider said no
		// reasoning ran; do not fall through to the char-count heuristic).
		return *raw.CompletionTokensDetails.ReasoningTokens, false
	}
	if raw.ReasoningTokens != nil && *raw.ReasoningTokens > 0 {
		return *raw.ReasoningTokens, false
	}
	// usage path absent; fall back to reasoning_content char-count estimate.
	if reasoningContent != "" {
		return len(reasoningContent) / 4, true
	}
	return 0, false
}

// extractMessageReasoningContent reads choices[0].message.reasoning_content
// from a full (non-streaming) Chat Completions response JSON. Providers that
// do thinking inline but do not populate completion_tokens_details (e.g. ds4)
// carry the thinking text here. Returns "" when absent or unparseable.
func extractMessageReasoningContent(rawCompletionJSON string) string {
	if rawCompletionJSON == "" {
		return ""
	}
	var raw struct {
		Choices []struct {
			Message struct {
				ReasoningContent string `json:"reasoning_content"`
			} `json:"message"`
		} `json:"choices"`
	}
	if err := json.Unmarshal([]byte(rawCompletionJSON), &raw); err != nil || len(raw.Choices) == 0 {
		return ""
	}
	return raw.Choices[0].Message.ReasoningContent
}

// Package anthropic implements a agent.Provider for the Anthropic Claude API.
package anthropic

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
	"strconv"
	"strings"
	"time"

	ant "github.com/anthropics/anthropic-sdk-go"
	"github.com/anthropics/anthropic-sdk-go/option"
	agent "github.com/easel/fizeau/internal/core"
	"github.com/easel/fizeau/internal/provider/quotaheaders"
	"github.com/easel/fizeau/internal/provider/registry"
)

func init() {
	registry.Register(registry.Descriptor{
		Type: "anthropic",
		Factory: func(in registry.Inputs) agent.Provider {
			return New(Config{
				BaseURL:             in.BaseURL,
				APIKey:              in.APIKey,
				Model:               in.Model,
				QuotaSignalObserver: in.QuotaSignalObserver,
			})
		},
		// Anthropic uses api.anthropic.com — no LAN-port inference,
		// explicit BaseURL (or SDK default) required.
	})
}

// Provider implements agent.Provider for the Anthropic Messages API.
type Provider struct {
	client         *ant.Client
	model          string
	providerName   string
	providerSystem string
	serverAddress  string
	serverPort     int
}

// Config holds configuration for the Anthropic provider.
type Config struct {
	APIKey  string
	Model   string // e.g., "claude-sonnet-4-20250514"
	BaseURL string
	// QuotaSignalObserver, when set, receives a parsed Anthropic rate-limit
	// signal on every HTTP response. The service layer wires this to the
	// provider quota state machine so subscription/daily exhaustion routes
	// dispatch around the provider until its reset window elapses.
	QuotaSignalObserver func(quotaheaders.Signal)
}

// New creates a new Anthropic provider.
func New(cfg Config) *Provider {
	opts := []option.RequestOption{option.WithMaxRetries(0)}
	if cfg.BaseURL != "" {
		opts = append(opts, option.WithBaseURL(cfg.BaseURL))
	}
	if cfg.APIKey != "" {
		opts = append(opts, option.WithAPIKey(cfg.APIKey))
	}
	if cfg.QuotaSignalObserver != nil {
		observer := cfg.QuotaSignalObserver
		opts = append(opts, option.WithMiddleware(func(req *http.Request, next option.MiddlewareNext) (*http.Response, error) {
			resp, err := next(req)
			if resp != nil {
				signal := quotaheaders.ParseAnthropic(resp.Header, time.Now())
				if signal.Present {
					observer(signal)
				}
			}
			return resp, err
		}))
	}
	client := ant.NewClient(opts...)
	serverAddress, serverPort := anthropicIdentity(cfg.BaseURL)
	return &Provider{
		client:         &client,
		model:          cfg.Model,
		providerName:   "anthropic",
		providerSystem: "anthropic",
		serverAddress:  serverAddress,
		serverPort:     serverPort,
	}
}

func (p *Provider) Chat(ctx context.Context, messages []agent.Message, tools []agent.ToolDef, opts agent.Options) (agent.Response, error) {
	model := p.model
	if opts.Model != "" {
		model = opts.Model
	}

	system, convMsgs := buildSystemBlocks(messages, opts)

	params := ant.MessageNewParams{
		Model:    ant.Model(model),
		Messages: convertMessages(convMsgs),
	}

	if len(system) > 0 {
		params.System = system
	}

	maxTokens := 4096
	if opts.MaxTokens > 0 {
		maxTokens = opts.MaxTokens
	}
	params.MaxTokens = int64(maxTokens)

	if opts.Temperature != nil {
		params.Temperature = ant.Float(*opts.Temperature)
	}

	if len(tools) > 0 {
		params.Tools = convertTools(tools, opts)
	}

	var resp agent.Response
	msg, err := p.client.Messages.New(ctx, params)
	if err != nil {
		return resp, fmt.Errorf("anthropic: %w", err)
	}

	resp.Model = string(msg.Model)
	resp.Attempt = &agent.AttemptMetadata{
		ProviderName:   p.providerName,
		ProviderSystem: p.providerSystem,
		ServerAddress:  p.serverAddress,
		ServerPort:     p.serverPort,
		RequestedModel: model,
		ResponseModel:  string(msg.Model),
		ResolvedModel:  string(msg.Model),
		Cost: &agent.CostAttribution{
			Source: agent.CostSourceUnknown,
		},
	}
	resp.Usage = agent.TokenUsage{
		Input:  int(msg.Usage.InputTokens),
		Output: int(msg.Usage.OutputTokens),
		Total:  int(msg.Usage.InputTokens + msg.Usage.OutputTokens),
	}

	// Extract cache tokens if present
	if msg.Usage.CacheCreationInputTokens > 0 {
		resp.Usage.CacheWrite = int(msg.Usage.CacheCreationInputTokens)
	}
	if msg.Usage.CacheReadInputTokens > 0 {
		resp.Usage.CacheRead = int(msg.Usage.CacheReadInputTokens)
	}

	resp.FinishReason = string(msg.StopReason)

	// Extract content and tool calls from content blocks
	for _, block := range msg.Content {
		switch block.Type {
		case "text":
			resp.Content += block.Text
		case "tool_use":
			resp.ToolCalls = append(resp.ToolCalls, agent.ToolCall{
				ID:        block.ID,
				Name:      block.Name,
				Arguments: json.RawMessage(block.Input),
			})
		}
	}

	return resp, nil
}

// SessionStartMetadata reports the broad provider identity and configured model
// that should be recorded on session.start events.
func (p *Provider) SessionStartMetadata() (string, string) {
	return p.providerName, p.model
}

// ChatStartMetadata reports the resolved provider system and upstream server
// identity known when the provider is constructed.
func (p *Provider) ChatStartMetadata() (string, string, int) {
	return p.providerSystem, p.serverAddress, p.serverPort
}

func convertMessages(msgs []agent.Message) []ant.MessageParam {
	var result []ant.MessageParam
	for _, m := range msgs {
		switch m.Role {
		case agent.RoleUser:
			result = append(result, ant.NewUserMessage(ant.NewTextBlock(m.Content)))
		case agent.RoleAssistant:
			if len(m.ToolCalls) > 0 {
				var blocks []ant.ContentBlockParamUnion
				if m.Content != "" {
					blocks = append(blocks, ant.NewTextBlock(m.Content))
				}
				for _, tc := range m.ToolCalls {
					var input interface{}
					_ = json.Unmarshal(tc.Arguments, &input)
					blocks = append(blocks, ant.NewToolUseBlock(tc.ID, input, tc.Name))
				}
				result = append(result, ant.NewAssistantMessage(blocks...))
			} else {
				result = append(result, ant.NewAssistantMessage(ant.NewTextBlock(m.Content)))
			}
		case agent.RoleTool:
			result = append(result, ant.NewUserMessage(
				ant.NewToolResultBlock(m.ToolCallID, m.Content, false),
			))
		}
	}
	return result
}

func convertTools(tools []agent.ToolDef, opts agent.Options) []ant.ToolUnionParam {
	var result []ant.ToolUnionParam
	for _, t := range tools {

---
	for _, t := range tools {
		var schema ant.ToolInputSchemaParam
		_ = json.Unmarshal(t.Parameters, &schema)

		result = append(result, ant.ToolUnionParam{
			OfTool: &ant.ToolParam{
				Name:        t.Name,
				Description: ant.String(t.Description),
				InputSchema: schema,
			},
		})
	}
	// Stamp an ephemeral cache_control breakpoint at the END of the tool list
	// so the entire tool prefix becomes a cacheable boundary. CachePolicy "off"
	// suppresses the marker.
	if len(result) > 0 && opts.CachePolicy != "off" {
		last := len(result) - 1
		if result[last].OfTool != nil {
			result[last].OfTool.CacheControl = ant.NewCacheControlEphemeralParam()
		}
	}
	return result
}

// buildSystemBlocks separates system messages from the conversation tail and
// returns the typed Anthropic system-block slice plus the remaining messages.
// When at least one system block is produced and CachePolicy is not "off",
// a cache_control: ephemeral breakpoint is set on the LAST block so the
// system prefix is cached.
func buildSystemBlocks(msgs []agent.Message, opts agent.Options) ([]ant.TextBlockParam, []agent.Message) {
	var system []ant.TextBlockParam
	var convMsgs []agent.Message
	for _, m := range msgs {
		if m.Role == agent.RoleSystem {
			system = append(system, ant.TextBlockParam{Text: m.Content})
		} else {
			convMsgs = append(convMsgs, m)
		}
	}
	if len(system) > 0 && opts.CachePolicy != "off" {
		system[len(system)-1].CacheControl = ant.NewCacheControlEphemeralParam()
	}
	return system, convMsgs
}

// ChatStream implements agent.StreamingProvider for token-level streaming.
func (p *Provider) ChatStream(ctx context.Context, messages []agent.Message, tools []agent.ToolDef, opts agent.Options) (<-chan agent.StreamDelta, error) {
	model := p.model
	if opts.Model != "" {
		model = opts.Model
	}

	system, convMsgs := buildSystemBlocks(messages, opts)

	params := ant.MessageNewParams{
		Model:    ant.Model(model),
		Messages: convertMessages(convMsgs),
	}
	if len(system) > 0 {
		params.System = system
	}
	maxTokens := 4096
	if opts.MaxTokens > 0 {
		maxTokens = opts.MaxTokens
	}
	params.MaxTokens = int64(maxTokens)
	if opts.Temperature != nil {
		params.Temperature = ant.Float(*opts.Temperature)
	}
	if len(tools) > 0 {
		params.Tools = convertTools(tools, opts)
	}

	stream := p.client.Messages.NewStreaming(ctx, params)

	ch := make(chan agent.StreamDelta, 1)
	go func() {
		defer close(ch)
		send := func(delta agent.StreamDelta) {
			delta.ArrivedAt = time.Now()
			ch <- delta
		}

		// Track current tool use block being streamed
		var currentToolID string
		var currentToolName string
		responseModel := model

		for stream.Next() {
			event := stream.Current()

			switch event.Type {
			case "message_start":
				// Capture input tokens from message_start
				if event.Message.Model != "" {
					responseModel = string(event.Message.Model)
				}
				send(agent.StreamDelta{
					Model: responseModel,
					Usage: &agent.TokenUsage{
						Input: int(event.Usage.InputTokens),
					},
				})

			case "content_block_start":
				if event.ContentBlock.Type == "tool_use" {
					currentToolID = event.ContentBlock.ID
					currentToolName = event.ContentBlock.Name
					send(agent.StreamDelta{
						ToolCallID:   currentToolID,
						ToolCallName: currentToolName,
					})
				}

			case "content_block_delta":
				// Text delta
				if event.Delta.Text != "" {
					send(agent.StreamDelta{Content: event.Delta.Text})
				}
				// Tool input JSON delta
				if event.Delta.PartialJSON != "" {
					send(agent.StreamDelta{
						ToolCallID:   currentToolID,
						ToolCallArgs: event.Delta.PartialJSON,
					})
				}

			case "content_block_stop":
				currentToolID = ""
				currentToolName = ""

			case "message_delta":
				delta := agent.StreamDelta{
					FinishReason: string(event.Delta.StopReason),
				}
				// Build usage with output and cache tokens
				usage := &agent.TokenUsage{}
				if event.Usage.OutputTokens > 0 {
					usage.Output = int(event.Usage.OutputTokens)
				}
				if event.Usage.CacheCreationInputTokens > 0 {
					usage.CacheWrite = int(event.Usage.CacheCreationInputTokens)
				}
				if event.Usage.CacheReadInputTokens > 0 {
					usage.CacheRead = int(event.Usage.CacheReadInputTokens)
				}
				if usage.Input > 0 || usage.Output > 0 || usage.CacheRead > 0 || usage.CacheWrite > 0 {
					delta.Usage = usage
				}
				send(delta)

			case "message_stop":
				if err := stream.Err(); err != nil {
					send(agent.StreamDelta{Err: err})
					return
				}
				send(agent.StreamDelta{
					Model: responseModel,
					Attempt: &agent.AttemptMetadata{
						ProviderName:   p.providerName,
						ProviderSystem: p.providerSystem,
						ServerAddress:  p.serverAddress,
						ServerPort:     p.serverPort,
						RequestedModel: model,
						ResponseModel:  responseModel,
						ResolvedModel:  responseModel,
						Cost: &agent.CostAttribution{
							Source: agent.CostSourceUnknown,
						},
					},
					Done: true,
				})
				return
			}
		}

		// Stream ended without message_stop — check for error.
		if err := stream.Err(); err != nil {
			send(agent.StreamDelta{Err: err})
			return
		}
		send(agent.StreamDelta{
			Model: responseModel,
			Attempt: &agent.AttemptMetadata{
				ProviderName:   p.providerName,
				ProviderSystem: p.providerSystem,
				ServerAddress:  p.serverAddress,
				ServerPort:     p.serverPort,
				RequestedModel: model,
				ResponseModel:  responseModel,
				ResolvedModel:  responseModel,
				Cost: &agent.CostAttribution{
					Source: agent.CostSourceUnknown,
				},
			},
			Done: true,
		})
	}()

	return ch, nil
}

var _ agent.Provider = (*Provider)(nil)
var _ agent.StreamingProvider = (*Provider)(nil)

func anthropicIdentity(baseURL string) (serverAddress string, serverPort int) {
	serverAddress = "api.anthropic.com"
	serverPort = 443

	if baseURL == "" {
		return serverAddress, serverPort
	}

	parsed, err := url.Parse(baseURL)
	if err != nil {
		return serverAddress, serverPort
	}

	if host := parsed.Hostname(); host != "" {
		serverAddress = host
	}

	if port := parsed.Port(); port != "" {
		if parsedPort, err := strconv.Atoi(port); err == nil {
			serverPort = parsedPort
		}
	} else if strings.EqualFold(parsed.Scheme, "http") {
		serverPort = 80
	}

	return serverAddress, serverPort
}

// Package discoverycache implements the per-source on-disk cache described in
// ADR-012. It provides a two-tier lock + long-lived refresh marker pattern so
// that slow discovery IO (PTY ~30 s, HTTP ~316 ms) never blocks UI reads.
//
// Public surface: Cache.Read, Cache.Refresh, Cache.MaybeRefresh, Cache.Prune.
// The Refresher function is injected; the cache manages single-flight
// deduplication, atomic writes, and crash recovery.
package discoverycache

import (
	"context"
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"time"

	"golang.org/x/sync/singleflight"
)

const (
	lockAcquisitionTimeout = 100 * time.Millisecond
	lockPollInterval       = 5 * time.Millisecond
	waitPollInterval       = 250 * time.Millisecond
	stalenessMultiplier    = time.Duration(2)
)

// Cache is the root handle. Root is the base directory (e.g. ~/.cache/fizeau).
// Each Cache instance owns one in-process singleflight.Group; a new Cache per
// process is the normal usage.
type Cache struct {
	Root string
	sf   singleflight.Group
}

// Source describes one cacheable data stream (one file under Root/Tier/Name.json).
type Source struct {
	// Tier is "discovery" or "runtime".
	Tier string
	// Name is the kebab-case source identifier (e.g. "openrouter").
	Name string
	// TTL controls freshness: Read returns Fresh=true when Age < TTL.
	TTL time.Duration
	// RefreshDeadline is the maximum time a refresh is expected to take.
	// Also controls the staleness threshold: 2 × RefreshDeadline.
	RefreshDeadline time.Duration
}

func (s Source) key() string { return s.Tier + "/" + s.Name }

// ReadResult is the output of Cache.Read.
type ReadResult struct {
	// Data is the raw bytes from the cache file; nil if no file exists.
	Data []byte
	// Age is how long ago the data was written (0 if absent).
	Age time.Duration
	// Fresh is true when Age < TTL and Data is non-nil.
	Fresh bool
	// Stale is true when Data is nil or Age >= TTL.
	Stale bool
}

// Refresher is the source-fetch function injected by the caller. The cache
// handles single-flight deduplication, the atomic write, and marker lifecycle.
type Refresher func(ctx context.Context) ([]byte, error)

// Read returns cached data without any IO beyond reading the local file.
// It never blocks on network or PTY. If no cache file exists, Data is nil and
// Stale is true. Stale data is always returned without error; the caller
// decides whether to trigger a background refresh.
func (c *Cache) Read(s Source) (ReadResult, error) {
	path := c.dataPath(s)
	data, err := os.ReadFile(path) // #nosec G304
	if errors.Is(err, os.ErrNotExist) {
		return ReadResult{Stale: true}, nil
	}
	if err != nil {
		return ReadResult{}, err
	}
	info, err := os.Stat(path)
	if err != nil {
		// File was just there; best-effort fallback.
		return ReadResult{Data: data, Stale: true}, nil
	}
	age := time.Since(info.ModTime())
	if age < 0 {
		age = 0
	}
	fresh := age < s.TTL
	return ReadResult{
		Data:  data,
		Age:   age,
		Fresh: fresh,
		Stale: !fresh,
	}, nil
}

// Prune removes data files (and their sidecar lock/marker/tmp files) for
// sources not listed in activeSources. Sources with an active .refreshing
// marker are skipped. Prune acquires the tier-1 lock before removing each
// source's files.
func (c *Cache) Prune(activeSources []Source) error {
	active := make(map[string]bool, len(activeSources))
	for _, s := range activeSources {
		active[s.key()] = true
	}

	return filepath.WalkDir(c.Root, func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return nil
		}
		if !strings.HasSuffix(d.Name(), ".json") {
			return nil
		}
		rel, rerr := filepath.Rel(c.Root, path)
		if rerr != nil {
			return nil
		}
		parts := strings.SplitN(rel, string(filepath.Separator), 2)
		if len(parts) != 2 {
			return nil
		}
		tier := parts[0]
		name := strings.TrimSuffix(parts[1], ".json")
		if strings.ContainsRune(name, filepath.Separator) {
			return nil // nested dir, skip
		}

		if active[tier+"/"+name] {
			return nil
		}

		s := Source{Tier: tier, Name: name}

		// Skip sources with an active refresh in progress.
		m, _ := readMarker(c.markerPath(s))
		if isMarkerActiveForPrune(m) {
			return nil
		}

		release, lerr := c.acquireLock(s)
		if lerr != nil {
			return nil // can't lock; skip this source
		}
		defer release()

		// Re-check under lock.
		m2, _ := readMarker(c.markerPath(s))
		if isMarkerActiveForPrune(m2) {
			return nil
		}

		_ = os.Remove(c.dataPath(s))
		_ = os.Remove(c.markerPath(s))
		_ = os.Remove(c.tmpPath(s))
		return nil
	})
}

// ---- internal ---------------------------------------------------------------

type claimResult struct {
	claimed bool
	marker  *refreshMarker
}

// claimRefresh implements Algorithm 1 from ADR-012. Must be called with the
// source directory already created (ensured by refreshAndCommit).
func (c *Cache) claimRefresh(s Source) (claimResult, error) {
	release, err := c.acquireLock(s)
	if err != nil {
		return claimResult{}, err
	}
	defer release()

	existing, _ := readMarker(c.markerPath(s))
	if existing != nil {
		if isStale(s, existing) {
			_ = os.Remove(c.markerPath(s))
		} else {
			return claimResult{claimed: false, marker: existing}, nil
		}
	}

	m := &refreshMarker{
		PID:       os.Getpid(),
		StartedAt: time.Now().UTC(),
		Deadline:  time.Now().UTC().Add(s.RefreshDeadline),
	}
	if werr := writeMarker(c.markerPath(s), m); werr != nil {
		return claimResult{}, werr
	}
	return claimResult{claimed: true}, nil
}

// refreshAndCommit implements Algorithm 2 from ADR-012.
func (c *Cache) refreshAndCommit(s Source, fn Refresher) error {
	if err := os.MkdirAll(filepath.Join(c.Root, s.Tier), 0o750); err != nil {
		return err
	}

	claim, err := c.claimRefresh(s)
	if err != nil {
		return err
	}
	if !claim.claimed {
		// Another process is refreshing; wait for it.
		return c.waitForRefresh(s, claim.marker)
	}

	// We hold the claim. Run slow IO outside any lock.
	data, fetchErr := fn(context.Background())
	if fetchErr != nil {
		c.releaseMarker(s)
		return fetchErr
	}

	if werr := atomicWrite(c.dataPath(s), data); werr != nil {
		c.releaseMarker(s)
		return werr
	}

	c.releaseMarker(s)
	return nil
}

// waitForRefresh implements Algorithm 3 from ADR-012. Polls until the marker
// disappears or becomes stale, then returns (data has been written).
func (c *Cache) waitForRefresh(s Source, m *refreshMarker) error {
	// Poll until deadline + staleness_threshold or s.RefreshDeadline, whichever first.
	threshold := s.RefreshDeadline * stalenessMultiplier
	absoluteDeadline := m.Deadline.Add(threshold)
	maxWait := time.Now().Add(s.RefreshDeadline)
	if maxWait.Before(absoluteDeadline) {
		absoluteDeadline = maxWait
	}

