func TestNew_AcceptsExplicitServiceConfig(t *testing.T) {
	sc := &stubServiceConfig{defaultName: "injected"}
	svc, err := fizeau.New(fizeau.ServiceOptions{ServiceConfig: sc})
	if err != nil {
