	"time"

	"github.com/easel/fizeau/internal/config"
	"github.com/easel/fizeau/internal/discoverycache"
)

var (
	defaultCacheOnce sync.Once
	defaultCache     *discoverycache.Cache
	defaultCacheErr  error
)

// Observe records one provider response into the in-memory runtime store and
// persists the refreshed signal to the default on-disk runtime cache.
func Observe(ctx context.Context, providerName, providerType string, headers http.Header, latency time.Duration) error {
	providerName = strings.TrimSpace(providerName)
	providerType = strings.TrimSpace(providerType)
	if providerName == "" {
		return nil
	}
	if ctx == nil || ctx.Err() != nil {
		ctx = context.Background()
	}

	RecordResponse(providerName, headers, latency, providerType)

	cache, err := defaultRuntimeCache()
	if err != nil {
		return err
	}
	sig, err := Collect(ctx, providerName, &config.ProviderConfig{Type: providerType})
	if err != nil {
		return err
	}
	return Write(cache, sig)
}

func defaultRuntimeCache() (*discoverycache.Cache, error) {
	defaultCacheOnce.Do(func() {
		root := strings.TrimSpace(os.Getenv("FIZEAU_CACHE_DIR"))
		if root == "" {
			var err error
			root, err = os.UserCacheDir()
			if err != nil {
				defaultCacheErr = err
				return
			}
			root = filepath.Join(root, "fizeau")
		}
		defaultCache = &discoverycache.Cache{Root: root}
	})
	return defaultCache, defaultCacheErr
}

