	sig, err := Collect(ctx, providerName, CollectInput{Type: providerType, BaseURL: baseURL})
	if err != nil {
		return err
	}
	if callErr != nil {
		now := time.Now().UTC()
		if sig.Status == StatusUnknown {
			sig.Status = StatusDegraded
		}
		sig.LastErrorAt = &now
		sig.LastErrorMsg = callErr.Error()
	}
	return Write(cache, sig)
}

